import json, pathlib, subprocess, tempfile, textwrap; repo = pathlib.Path.cwd(); fz = repo / 'target/debug/fz'

def write_project(name, source):
    root = pathlib.Path(tempfile.mkdtemp(prefix=f'fozzylang-{name}-'))
    (root / 'src').mkdir(parents=True, exist_ok=True)
    (root / 'fozzy.toml').write_text(textwrap.dedent(f'''\
        [package]
        name="{name}"
        version="0.1.0"

        [[target.bin]]
        name="{name}"
        path="src/main.fzy"
    '''))
    (root / 'src/main.fzy').write_text(textwrap.dedent(source))
    return root

def verify(name, source, expect_rc):
    root = write_project(name, source)
    proc = subprocess.run([str(fz), 'verify', str(root), '--json'], cwd=str(repo), capture_output=True, text=True)
    payload = json.loads(proc.stdout.strip())
    assert proc.returncode == expect_rc, (name, proc.returncode, payload, proc.stderr)
    return root, payload

def find(payload, needle):
    return next(item for item in payload['items'] if needle in item['message'])

http_root, http_payload = verify('spawn_http_handle', '''
    use core.http;
    use core.thread;
    fn main() -> i32 {
        let conn = http.accept()
        let worker = | | http.path(conn)
        let handle = spawn(worker)
        return join(handle)
    }
''', 1)
http_diag = find(http_payload, 'spawn captures non-Send-safe handle `conn` (HttpHandle) across thread boundary')
assert 'move only Send-safe handles into spawned tasks' in (http_diag.get('help') or ''), http_diag

file_root, file_payload = verify('spawn_file_handle', '''
    use core.fs;
    use core.thread;
    fn main() -> i32 {
        let file = fs.open("/tmp/fzy-handle-boundary-file.txt")
        let worker = | | fs.flush(file)
        let handle = spawn(worker)
        return join(handle)
    }
''', 1)
file_diag = find(file_payload, 'spawn captures non-Send-safe handle `file` (FileHandle) across thread boundary')
assert 'finish/close the non-Send-safe handle before crossing the thread boundary' in (file_diag.get('help') or ''), file_diag

argv_root, argv_payload = verify('await_process_argv', '''
    use core.proc;
    async fn worker() -> i32 {
        let argv = proc.argv_new()
        await recv()
        discard argv
        return 0
    }
    fn main() -> i32 {
        return 0
    }
''', 1)
argv_diag = find(argv_payload, 'cannot use non-async-stable handle `argv` (ProcessArgv) across await suspension points')
assert 'finish, consume, or replace the non-async-stable handle before `await`' in (argv_diag.get('help') or ''), argv_diag

env_root, env_payload = verify('await_process_env', '''
    use core.proc;
    async fn worker() -> i32 {
        let env = proc.env_new()
        await recv()
        discard env
        return 0
    }
    fn main() -> i32 {
        return 0
    }
''', 1)
env_diag = find(env_payload, 'cannot use non-async-stable handle `env` (ProcessEnv) across await suspension points')
assert 'finish, consume, or replace the non-async-stable handle before `await`' in (env_diag.get('help') or ''), env_diag

clean_root, clean_payload = verify('send_safe_list_capture', '''
    use core.thread;
    fn main() -> i32 {
        let payload = json.parse("[1,2,3]")
        let items = json.to_list(payload)
        let worker = | | list.len(items)
        let handle = spawn(worker)
        return join(handle)
    }
''', 0)
assert clean_payload['errors'] == 0, clean_payload
assert not any('non-Send-safe handle' in item['message'] or 'non-async-stable handle' in item['message'] for item in clean_payload['items']), clean_payload
handle_contracts = json.loads((clean_root / '.fz' / 'handle-contracts.json').read_text())['handles']
handle_map = {entry['name']: entry for entry in handle_contracts}
assert handle_map['FileHandle']['sendSafe'] is False and handle_map['FileHandle']['asyncStable'] is True, handle_map['FileHandle']
assert handle_map['ProcessArgv']['sendSafe'] is False and handle_map['ProcessArgv']['asyncStable'] is False, handle_map['ProcessArgv']
assert handle_map['ListHandle']['sendSafe'] is True and handle_map['ListHandle']['asyncStable'] is True, handle_map['ListHandle']
assert handle_map['TaskHandle']['sendSafe'] is True and handle_map['TaskHandle']['linear'] is True, handle_map['TaskHandle']
print('compiler-handle-matrix-boundaries-ok')

